import React, { useEffect } from "react";
import { makeStyles } from '@mui/styles';
import Card from "@mui/material/Card";
import Table from "@mui/material/Table";
import TableBody from "@mui/material/TableBody";
import TableCell from "@mui/material/TableCell";
import TableContainer from "@mui/material/TableContainer";
import TableHead from "@mui/material/TableHead";
import TableRow from "@mui/material/TableRow";
import Paper from "@mui/material/Paper";
import Box from '@mui/material/Box';
import CircularProgress from '@mui/material/CircularProgress';
import {
  useTable,
  useRowSelect,
  useSortBy,
  useGlobalFilter,
  usePagination,
} from "react-table";
import Loader from "src/routes/Loader";

const useStyles = makeStyles({
  responsiveTable: {
    width: "100%",
    overflowX: "auto",
  },
  tableTh: {
    whiteSpace: "nowrap",
  },
  tableTd: {
    // textAlign: "center",
    whiteSpace: "nowrap",
  },
  noBreak: {
    wordWrap: "normal",
    whiteSpace: "nowrap",
  },
  noDataFound: {
    display: "flex",
    justifyContent: "center",
    alignItems: "center",
    height: "100%",
    width: "100%",
    color: "red",
  },
  '@media (max-width: 768px)': {
    responsiveTable: {
      display: "block",
      overflowX: "auto",
    },
    tableTh: {
      whiteSpace: "normal",
    },
    tableTd: {
      whiteSpace: "normal",
      textAlign: "left",
    },
  },
});

const TanstackTable = ({ data, columns, fetchResult, total = 1, perPage = 10, loading }) => {
  const classes = useStyles();
  let serverSide = false;
  if (fetchResult) {
    serverSide = true;
  }

  const tableInstance = useTable(
    {
      columns,
      data,
      initialState: { pageIndex: 0 },
      pageCount: Math.ceil(total / perPage),
      manualPagination: serverSide,
      manualSortBy: serverSide,
      manualFilters: serverSide,
      manualGlobalFilter: serverSide,
    },
    useGlobalFilter,
    useSortBy,
    usePagination,
    useRowSelect
  );

  const {
    getTableProps,
    getTableBodyProps,
    headerGroups,
    page,
    state,
    prepareRow, rows
  } = tableInstance;

  const { pageIndex } = state;

  useEffect(() => {
    if (fetchResult) fetchResult(pageIndex + 1);
  }, [pageIndex]);

  return (
    <Card>
      <TableContainer component={Paper} className={classes.responsiveTable}>
        <Table {...getTableProps()}>
          <TableHead>
            {headerGroups.map((headerGroup) => (
              <TableRow {...headerGroup.getHeaderGroupProps()}>
                {headerGroup.headers.map((column) => (
                  <TableCell
                    {...column.getHeaderProps(column.getSortByToggleProps())}
                    className={classes.tableTh}
                  >
                    {column.render("Header")}
                    <span>
                      {column.isSorted ? (column.isSortedDesc ? " 🔽" : " 🔼") : ""}
                    </span>
                  </TableCell>
                ))}
              </TableRow>
            ))}
          </TableHead>
          <TableBody {...getTableBodyProps()} className="relative">
            {/* {page.length > 0 ? (
              page.map((row) => {
                prepareRow(row);
                return (
                  <TableRow {...row.getRowProps()} key={row.id}>
                    {row.cells.map((cell) => (
                      <TableCell
                        {...cell.getCellProps()}
                        className={`${classes.tableTd} ${classes.noBreak}`}
                        key={cell.column.id}
                      >
                        {cell.render("Cell")}
                      </TableCell>
                    ))}
                  </TableRow>
                );
              })
            ) : (
              <TableRow>
                <TableCell colSpan={columns.length} className={classes.tableTd}>
                  <div className={classes.noDataFound}>
                    <p>No Data Found</p>
                  </div>
                </TableCell>
              </TableRow>
            )} */}

            {page.length > 0 && !loading ? (
              page.map((row) => {
                prepareRow(row);
                return (
                  <TableRow {...row.getRowProps()} key={row.id}>
                    {row.cells.map((cell) => (
                      <TableCell
                        {...cell.getCellProps()}
                        className={`${classes.tableTd} ${classes.noBreak}`}
                        key={cell.column.id}
                      >
                        {cell.render("Cell")}
                      </TableCell>
                    ))}
                  </TableRow>
                );
              })
            ) : (
               <div style={{
                marginLeft:'20px',
                marginTop:'20px',
                marginBottom:'20px'
               }}>loading...</div>
              // <Loader/>
              
            )}

          </TableBody>
        </Table>
      </TableContainer>
    </Card>
  );
};

export default TanstackTable;
