import React from 'react';
import {
    useReactTable,
    getCoreRowModel,
    getPaginationRowModel,
    flexRender,
} from '@tanstack/react-table';
import { styled } from '@mui/material/styles';
import {
    Table,
    TableHead,
    TableRow,
    TableCell,
    TableBody,
    TextField,
    Box,
    Typography,
} from '@mui/material';
import SkeletonTable from './SkeletonTable';
import { useMyContext } from '../../pages/provider';

const StyledTableRow = styled(TableRow)(({ theme }) => ({
    '&:nth-of-type(even)': {
        backgroundColor: theme.palette.action.hover,
    },
    '&:last-child td, &:last-child th': {
        border: 0,
    },
}));

const dateField = ['createdAt', 'updatedAt', 'checkIn', 'start', 'checkOut', 'end', 'paidDate', 'cancleDate', 'addedAt'];
const selectionStatus = ['isActive', 'cancellationPolicyId', 'status', 'Publish', 'Status', 'publish'];
const phoneNumber = ['phone'];
const email = ['email']


export default function TanstackTableV8({
    data = [],
    columns = [],
    filters = {},
    onFilterChange,
    isLoading = false,
}) {
    const table = useReactTable({
        data,
        columns,
        getCoreRowModel: getCoreRowModel(),
        getPaginationRowModel: getPaginationRowModel(),
    });

    const { i18 } = useMyContext();

    const hasFilters = columns.some((column) => column?.showFilter)

    return (
        <Box>
            <Table>
                <TableHead>
                    {table.getHeaderGroups().map((headerGroup) => (
                        <TableRow key={headerGroup.id}>
                            {headerGroup.headers.map((header) => (
                                <TableCell
                                    key={header.id}
                                    sx={{
                                        fontWeight: 'bold',
                                        whiteSpace: 'nowrap',
                                    }}
                                >
                                    {header.isPlaceholder
                                        ? null
                                        : flexRender(header.column.columnDef.header, header.getContext())}
                                </TableCell>
                            ))}
                        </TableRow>
                    ))}
                </TableHead>
                    { hasFilters && <TableRow>
                        {columns.map((column) => (
                            <TableCell key={column.id}>
                                {column?.showFilter && (
                                    <>
                                    {/* {phoneNumber.includes()} */}
                                    <TextField
                                        label={`${column?.header}`}
                                        variant="outlined"
                                        size="small"
                                        value={filters[column?.id] || ''}
                                        onChange={(e) => onFilterChange(column?.id, e.target.value)}
                                        InputLabelProps={{ shrink: true }}
                                        type={dateField.includes(column?.id) ? 'date' : 'text'}
                                    />
                                    </>
                                )}
                            </TableCell>
                        ))}
                    </TableRow> }
                <TableBody>
                    {isLoading ? (
                        <TableRow>
                            <TableCell colSpan={columns.length} align="center">
                                <SkeletonTable rowHeight="74px" rows={5} columns={columns.length} />
                            </TableCell>
                        </TableRow>
                    ) : data.length === 0 ? (
                        <TableRow>
                            <TableCell colSpan={columns.length} align="center">
                                <Typography variant="body1">{i18?.LISTINGPAGE?.NOT_FOUND|| "No Data Found"}</Typography>
                            </TableCell>
                        </TableRow>
                    ) : (
                        table.getRowModel().rows.map((row) => (
                            <StyledTableRow hover key={row.id}>
                                {row.getVisibleCells().map((cell) => (
                                    <TableCell
                                        key={cell.id}
                                        sx={{
                                            whiteSpace: 'nowrap',
                                        }}
                                    >
                                        {flexRender(cell.column.columnDef.cell, cell.getContext())}
                                    </TableCell>
                                ))}
                            </StyledTableRow>
                        ))
                    )}
                </TableBody>
            </Table>
        </Box>
    );
}

